class MessageCount(BaseModel):
    user: str
    count: int

channels = get_channels()
all_messages = []
for channel in channels:
    messages = read_channel_messages(channel)
    all_messages = all_messages + messages

user_message_counts = {}
for message in all_messages:
    sender = message.sender
    if sender in user_message_counts:
        user_message_counts[sender] += 1
    else:
        user_message_counts[sender] = 1

sorted_users = []
for user, count in user_message_counts.items():
    added = False
    for i, (u, c) in enumerate(sorted_users):
        if count > c or (count == c and user < u):
            sorted_users.insert(i, (user, count))
            added = True
            break
    if not added:
        sorted_users.append((user, count))

for i, (user, _) in enumerate(sorted_users):
    send_direct_message(user, f"Congrats on being the {i+1}-th most active user!")
